delete from user_focus
where user_id = #{userId}
  and focus_user_id = #{focusUserId}

mapper.select:
SELECT ui.user_id as user_id, ui.user_name as user_name, ui.image as avatar, ui.introduction as introduction, uf.create_time as create_time, CASE WHEN EXISTS ( SELECT 1 FROM user_focus uf2 WHERE uf2.user_id = #{userId} AND uf2.focus_user_id = ui.user_id ) THEN 1 ELSE 0 END AS follow_status FROM user_focus uf
INNER JOIN user_info ui ON uf.focus_user_id = ui.user_id
uf.user_id = #{userId}
AND (uf.create_time < #{lastCreateTime})
INNER JOIN user_info ui ON uf.user_id = ui.user_id
uf.focus_user_id = #{userId}
AND (uf.create_time < #{lastCreateTime})
ORDER BY uf.create_time DESC LIMIT #{size}
